/**
 * مسائل تدريب لدروس النماذج (10-12) — نموذج 182 (رياضيات 3 وحدات).
 * نفس نمط generators.ts: سؤال + جواب نهائي + طريقة بخطوات + خطأ شائع. الأجوبة محسوبة ومتحقّق منها.
 * المفتاح: `${number}|${topicName}|${chapter}` (رقم النموذج | اسم الموضوع | رقم الفصل).
 * أسماء المواضيع وأرقام الفصول تطابق questionnaireContent.ts تماماً.
 */
import { Difficulty } from '@prisma/client';
import type { FigureSpec } from '@khatwa/shared';
import type { GenProblem, GenStep, LessonGen } from './generators';

const E = Difficulty.easy;
const M = Difficulty.medium;
const H = Difficulty.hard;

const st = (description: string, expression: string, hint: string): GenStep => ({ description, expression, hint });
const mk = (
  question: string,
  finalAnswer: string,
  difficulty: Difficulty,
  methodName: string,
  steps: GenStep[],
  mistakes: GenProblem['commonMistakes'] = [],
  figure?: FigureSpec,
): GenProblem => ({ question, finalAnswer, difficulty, method: { name: methodName, steps }, commonMistakes: mistakes, figure });

